BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE canonization_records (record_id uuid PRIMARY KEY, schema_version text NOT NULL, candidate_status text NOT NULL CHECK (candidate_status = 'CANDIDATE_DRAFT  NOT ADMITTED'), current_version integer NOT NULL DEFAULT 1, current_hash text NOT NULL, source_hash text NOT NULL, record jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE record_versions (record_id uuid NOT NULL REFERENCES canonization_records(record_id), version integer NOT NULL, content_hash text NOT NULL, schema_version text NOT NULL, record jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(record_id,version));
CREATE TABLE source_artifacts (source_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES canonization_records(record_id), source_uri text, content_hash text NOT NULL, coordinates jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE recovered_objects (object_id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), object_type text NOT NULL, body jsonb NOT NULL);
CREATE TABLE dependency_edges (edge_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES canonization_records(record_id), from_object uuid, to_object uuid, edge_type text NOT NULL, body jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE classifications (classification_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES canonization_records(record_id), object_id uuid, classification_kind text NOT NULL, body jsonb NOT NULL);
CREATE TABLE claims (claim_id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), body jsonb NOT NULL);
CREATE TABLE evidence (evidence_id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), body jsonb NOT NULL);
CREATE TABLE proofs (proof_id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), body jsonb NOT NULL);
CREATE TABLE bridges (bridge_id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), proof_propagation boolean NOT NULL DEFAULT false CHECK (proof_propagation = false), body jsonb NOT NULL);
CREATE TABLE countermodels (countermodel_id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), body jsonb NOT NULL);
CREATE TABLE lean_receipts (receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES canonization_records(record_id), source_hash text NOT NULL, result_hash text NOT NULL, body jsonb NOT NULL);
CREATE TABLE reviews (review_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES canonization_records(record_id), record_version integer NOT NULL, reviewer text NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE votes (vote_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES canonization_records(record_id), voter text NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admission_events (admission_event_id uuid PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), record_version integer NOT NULL, governed_by text NOT NULL, signature_reference text NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE projection_state (record_id uuid NOT NULL REFERENCES canonization_records(record_id), projection_type text NOT NULL, projection_hash text NOT NULL, synchronized_at timestamptz, PRIMARY KEY(record_id,projection_type));
CREATE TABLE cached_drafts (draft_id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES canonization_records(record_id), base_hash text NOT NULL, version integer NOT NULL, draft jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE synchronization_receipts (synchronization_key text PRIMARY KEY, record_id uuid NOT NULL REFERENCES canonization_records(record_id), record_version integer NOT NULL, content_hash text NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE VIEW ai_candidate_records AS SELECT record_id,schema_version,current_version,current_hash,source_hash,record FROM canonization_records WHERE NOT EXISTS (SELECT 1 FROM admission_events a WHERE a.record_id=canonization_records.record_id);
COMMIT;
